const startedAt = Date.now();
const binaryData = items[0].binary || {};
const firstKey = binaryData.audio ? 'audio' : Object.keys(binaryData)[0];
if (!firstKey) {
  throw new Error('Missing audio binary upload');
}
return [{
  json: {
    ...(items[0].json || {}),
    _pipelineStartedAt: startedAt,
    _uploadStartedAt: Date.now()
  },
  binary: { audio: binaryData[firstKey] }
}];

const prev = items[0].json || {};
const startNode = $('Normalize Binary & Start Timer').first().json;
const attempt = Number(prev._pollAttempt || 0);
const scheduleSec = [2, 3, 5, 8, 10];
const waitSeconds = scheduleSec[Math.min(attempt, scheduleSec.length - 1)];
const now = Date.now();
return [{
  json: {
    ...prev,
    _pollAttempt: attempt + 1,
    _waitSeconds: waitSeconds,
    _pollingWaitMs: Number(prev._pollingWaitMs || 0) + waitSeconds * 1000,
    _assemblyAiUploadMs: prev._assemblyAiUploadMs || (now - (startNode._uploadStartedAt || now)),
    _transcriptionStartedAt: prev._transcriptionStartedAt || now
  }
}];

const tr = items[0].json;
const pollMeta = $('Adaptive Poll Scheduler (2s-3s-5s-8s-10s)').first().json;
const now = Date.now();
const words = Array.isArray(tr.words) ? tr.words : [];
const avgConf = words.length ? Math.round((words.reduce((s, w) => s + (Number(w.confidence) || 0), 0) / words.length) * 10000) / 10000 : (typeof tr.confidence === 'number' ? tr.confidence : null);
return [{
  json: {
    transcript_id: tr.id,
    transcript_text: tr.text || '',
    raw_transcript: tr.text || '',
    transcript_utterances: tr.utterances || [],
    language_code: tr.language_code || 'auto',
    speech_model_used: tr.speech_model_used || tr.speech_model || 'assemblyai-stt-3-7',
    average_confidence: avgConf,
    diarization_enabled: true,
    audio_duration: tr.audio_duration || 0,
    _assemblyAiUploadMs: pollMeta._assemblyAiUploadMs || 0,
    _pollingWaitMs: pollMeta._pollingWaitMs || 0,
    _pollCount: pollMeta._pollAttempt || 0,
    _transcriptionMs: Math.max(1, now - (pollMeta._transcriptionStartedAt || now)),
    _geminiStartedAt: now
  }
}];

