const trNode = $('Prepare Transcript & Timing').first().json;
const rawText = items[0].json?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
let analysis = {};
try {
  analysis = JSON.parse(rawText);
} catch {
  analysis = { summary: rawText };
}
const geminiAnalysisMs = Math.max(1, Date.now() - (trNode._geminiStartedAt || Date.now()));
return [{
  json: {
    success: true,
    timings: {
      assemblyAiUploadMs: trNode._assemblyAiUploadMs || 0,
      transcriptionMs: trNode._transcriptionMs || 0,
      pollingWaitMs: trNode._pollingWaitMs || 0,
      pollCount: trNode._pollCount || 0,
      geminiAnalysisMs
    },
    transcript: {
      id: trNode.transcript_id,
      text: trNode.transcript_text,
      rawText: trNode.raw_transcript || trNode.transcript_text,
      utterances: trNode.transcript_utterances || [],
      language: trNode.language_code || 'auto',
      asrModel: trNode.speech_model_used || 'assemblyai-stt-3-7',
      averageConfidence: trNode.average_confidence,
      diarizationEnabled: trNode.diarization_enabled !== false,
      durationSeconds: trNode.audio_duration || 0
    },
    analysis
  }
}];
